{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    n = len(nodes)

    # Validate required fields
    if not nodes or not core_distance or distances is None:
        raise ValueError("Missing required fields")

    # Compute mutual reachability edges: max(core_left, core_right, distance)
    mr_edges = []
    for edge in distances:
        u, v, d = edge[0], edge[1], edge[2]
        # Canonicalize undirected endpoints lexicographically
        if u > v:
            u, v = v, u
        mr = max(core_distance[u], core_distance[v], d)
        mr_edges.append((u, v, mr))

    # Sort by reachability weight then endpoint IDs for determinism
    mr_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    # Kruskal's MST
    mst_edges = []
    total_weight = 0.0

    for u, v, w in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Input graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
